"use client";
import { useState } from "react";
import { api } from "@/lib/api/client";
import type { ConsultationPayload } from "@/types/api";

const initial: ConsultationPayload = { name:"", email:"", phone:"", services_type:"", preferred_date:"", message:"" };
export function ConsultationForm(){ const [form,setForm]=useState(initial); const [state,setState]=useState<"idle"|"sending"|"success"|"error">("idle"); const update=(key:keyof ConsultationPayload,value:string)=>setForm(f=>({...f,[key]:value})); async function submit(e:React.FormEvent){e.preventDefault();setState("sending");try{await api.consultation(form);setForm(initial);setState("success")}catch{setState("error")}} return <form onSubmit={submit} className="grid gap-7" noValidate><div className="grid gap-7 md:grid-cols-2"><label>الاسم<input required className="field" value={form.name} onChange={e=>update("name",e.target.value)} /></label><label>البريد الإلكتروني<input required type="email" className="field" value={form.email} onChange={e=>update("email",e.target.value)} /></label><label>رقم الهاتف<input required type="tel" pattern="[0-9+\\s-]{7,20}" className="field" value={form.phone} onChange={e=>update("phone",e.target.value)} /></label><label>نوع الخدمة / المشروع<input required className="field" value={form.services_type} onChange={e=>update("services_type",e.target.value)} /></label><label>التاريخ المفضّل<input required type="date" className="field" value={form.preferred_date} onChange={e=>update("preferred_date",e.target.value)} /></label></div><label>الرسالة<textarea required rows={4} className="field resize-none" value={form.message} onChange={e=>update("message",e.target.value)} /></label><button disabled={state==="sending"} className="button button-solid w-fit disabled:opacity-50">{state==="sending" ? "جارٍ الإرسال…" : "إرسال الطلب ←"}</button>{state==="success"&&<p className="text-[#52604d]">تم استلام طلبك. سنتواصل معك قريباً.</p>}{state==="error"&&<p className="text-red-700">تعذر إرسال الطلب حالياً. يرجى المحاولة مرة أخرى.</p>}</form> }
